using Microsoft.CodeAnalysis;
using ZeroLog.Analyzers.Support;

namespace ZeroLog.Analyzers;

public abstract class SourceGeneratorBase : IIncrementalGenerator
{
    public abstract void Initialize(IncrementalGeneratorInitializationContext context);

    private protected abstract class GeneratorBase
    {
        protected readonly CodeWriter _writer = new();

        protected void AppendCommonHeader(string generatorName)
        {
            _writer.AppendLine(
                $"""
                // <auto-generated>
                //   This file was generated by ZeroLog to provide additional optimizations.
                //
                //   If needed, it can be disabled by setting the <c>ZeroLogGenerate{generatorName}</c> MSBuild property to <c>false</c>.
                //   All ZeroLog source generators can be disabled by setting the <c>ZeroLogSourceGenerators</c> MSBuild property to <c>false</c>.
                // </auto-generated>

                #nullable enable

                """
            );
        }
    }
}
